from copy import deepcopy

from solution import page

rows = [
    {\"id\": \"z\", \"score\": -2, \"team\": \"red\"},
    {\"id\": \"c\", \"score\": 5, \"team\": \"red\"},
    {\"id\": \"b\", \"score\": 5, \"team\": \"blue\"},
    {\"id\": \"a\", \"score\": 5, \"team\": \"red\", \"extra\": {\"value\": 1}},
    {\"id\": \"w\", \"score\": 9, \"team\": \"red\"},
]
original = deepcopy(rows)
assert page(rows, 2, None, \"red\") == {\"rows\": [rows[4], rows[3]], \"next\": [5, \"a\"]}
assert page(rows, 2, [5, \"a\"], \"red\") == {\"rows\": [rows[1], rows[0]], \"next\": None}
assert page(rows, 1, [5, \"b\"], \"red\") == {\"rows\": [rows[1]], \"next\": [5, \"c\"]}
assert page(rows, 50, [5, \"bb\"], None) == {\"rows\": [rows[1], rows[0]], \"next\": None}
assert page(rows, 50, [-2, \"z\"], None) == {\"rows\": [], \"next\": None}
assert page(rows, 50, None, \"\") == {\"rows\": [], \"next\": None}
assert rows == original
for limit in (0, 51, 1.5, True):
    try:
        page(rows, limit, None, None)
    except ValueError:
        continue
    raise AssertionError(f\"Accepted invalid limit {limit"'!r}")
print("Edge cases passed")
PY'

